import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// The mobile app ships an English catalogue as its FLOOR: until the server's
// answer lands - and forever, if that request fails - every t() resolves against
// it. Hand-maintained, that floor held 74 keys out of 2878, so a cold start
// painted raw keys on the first screen a viewer sees: the header search read
// "media.search.placeholder" (emulator, 2026-09-05).
//
// It is now generated by scripts/i18n-fixture.py from i18n/en/*.yaml, the same
// source as the web fixture. This fails if the two ever diverge again - which is
// what a hand-edited floor eventually does.

const MOBILE_FALLBACK = join(__dirname, "..", "i18n", "fallback.en.json");
const WEB_FIXTURE = join(__dirname, "..", "..", "..", "web", "src", "test", "en-translations.json");

function load(path: string): Record<string, string> {
  return JSON.parse(readFileSync(path, "utf8")) as Record<string, string>;
}

describe("embedded English fallback", () => {
  it("carries every key the catalogue defines", () => {
    const fallback = load(MOBILE_FALLBACK);
    const full = load(WEB_FIXTURE);
    const missing = Object.keys(full).filter((k) => !(k in fallback));
    expect(
      missing.slice(0, 20),
      `${missing.length} keys are missing from the embedded floor. Every screen using one of them ` +
        "renders the raw key until the server catalogue arrives. Run: python3 scripts/i18n-fixture.py",
    ).toEqual([]);
  });

  it("says the same thing as the catalogue, key for key", () => {
    const fallback = load(MOBILE_FALLBACK);
    const full = load(WEB_FIXTURE);
    const differing = Object.keys(full).filter((k) => fallback[k] !== full[k]);
    expect(differing.slice(0, 20)).toEqual([]);
  });

  // The floor is the first screen a viewer reads. If this key is absent the
  // search bar on the home screen shows its own name.
  it("covers the header search placeholder", () => {
    expect(load(MOBILE_FALLBACK)["media.search.placeholder"]).toBeTruthy();
  });
});
